double f(double x) {
    return 2.0 * x + 3.0;
}

double Trap(double left, double right, int count, double base_len) {
    double estimate = (f(left) + f(right)) / 2.0;
    for (int i = 1; i < count; i++) {
        double x = left + i * base_len;
        estimate += f(x);
    }
    return estimate * base_len;
}

